import type { TemplateFormat } from './template.ts'

// The neutral templates of the library: generated by `tools/templates/` without data or logos
// and loaded by `scripts/templates-publish.ts`. The letterhead is uploaded by the Admin.

/** The slug of the neutral template of each format: the one a recipe without a template uses. */
export const NEUTRAL_TEMPLATE_SLUGS: Readonly<Record<TemplateFormat, string>> = {
  docx: 'neutro-docx',
  pptx: 'neutro-pptx',
  xlsx: 'neutro-xlsx',
}

/** The slug of the workbook of the SAL, a form filled through its named cells. */
export const SAL_TEMPLATE_SLUG = 'modulo-sal'

/**
 * The names of the cells of the SAL form, fixed by its generator. A name of a single value holds
 * that value; a name of a column (`position_*`) is the first row of the column, filled downward.
 */
export const SAL_CELL_NAMES = {
  orderNumber: 'order_number',
  orderDate: 'order_date',
  orderCustomer: 'order_customer',
  orderTotal: 'order_total',
  requestNumber: 'request_number',
  requestPeriod: 'request_period',
  requestAmount: 'request_amount',
  requestedToDate: 'requested_to_date',
  remainingAmount: 'remaining_amount',
  positionItem: 'position_item',
  positionAmount: 'position_amount',
  positionPreviousPct: 'position_previous_pct',
  positionCurrentPct: 'position_current_pct',
  positionPeriodPct: 'position_period_pct',
  positionPeriodAmount: 'position_period_amount',
} as const
export type SalCellName = (typeof SAL_CELL_NAMES)[keyof typeof SAL_CELL_NAMES]
